using System.Diagnostics.CodeAnalysis;

namespace Scarlet.Orleans.Relational;

/// <summary>
/// ETags are GUIDs generated by the client and stored as 16 bytes on every engine.
/// </summary>
/// <remarks>
/// Bytes rather than native GUID types avoid the per-driver byte orders of <c>uniqueidentifier</c> and MySQL GUID
/// formats, so the same value round-trips through every driver and both flavours.
/// </remarks>
internal static class ETags
{
    public static byte[] New(TimeProvider timeProvider) => Guid.CreateVersion7(timeProvider.GetUtcNow()).ToByteArray();

    public static string Format(byte[] etag) => new Guid(etag).ToString("N");

    /// <summary>
    /// Parses an ETag handed out by <see cref="Format"/>. Anything else cannot match a stored row.
    /// </summary>
    public static bool TryParse(string? etag, [NotNullWhen(true)] out byte[]? bytes)
    {
        if (Guid.TryParseExact(etag, "N", out var guid))
        {
            bytes = guid.ToByteArray();
            return true;
        }

        bytes = null;
        return false;
    }
}
